#include <cstdio>
#include <queue>
using std :: priority_queue;
using std :: greater;
using std :: vector;

int n, ans = 0;
priority_queue < int, vector <int>, greater <int> > q;
int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i)
	{
		int x; scanf("%d", &x);
		q.push(x);
	}
	while(q.size() > 1)
	{
		int x = q.top(); q.pop();
		int y = q.top(); q.pop();
		ans += x + y;
		q.push(x + y);
	}
	printf("%d\n", ans);
	return 0;
}

#include<cstdio>
#include<algorithm>
#include<cstring>
using namespace std;
int k,x,num,n1,n2,a1[30001],a2[30001],t[20001],w,sum;
int main()
{
	scanf("%d",&num);
	memset(a1,127/3,sizeof(a1));
	memset(a2,127/3,sizeof(a2));
	for (int i=1;i<=num;i++)
	{
		scanf("%d",&x);
		t[x]++; 
	}
	for (int i=1;i<=20000;i++)
	{
		while (t[i]) 
		{
			t[i]--;
			a1[++n1]=i;
		}
	}
	int i=1,j=1;
	k=1;
	while (k<num)
	{
		if (a1[i]<a2[j]) 
		{
			w=a1[i];
			i++;
		}
		else
		{
			w=a2[j];
